package com.fooddelivery.delivery.service;
import com.fooddelivery.delivery.client.OrderClient; import com.fooddelivery.delivery.entity.*; import com.fooddelivery.delivery.repository.*; import jakarta.persistence.EntityNotFoundException; import java.math.BigDecimal; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.kafka.core.KafkaTemplate; import tools.jackson.databind.ObjectMapper;
@Service @Transactional(readOnly=true) public class DeliveryService {private final DeliveryRepository deliveries;private final DeliveryItemRepository items;private final NotificationRepository notifications;private final DriverPresenceRepository driverPresence;private final OrderClient orders;private final String internalKey;
 private final KafkaTemplate<String,String> kafka;private final ObjectMapper mapper;private final SmsNotificationService sms;
 public DeliveryService(DeliveryRepository d,DeliveryItemRepository i,NotificationRepository n,DriverPresenceRepository presence,OrderClient o,KafkaTemplate<String,String> kafka,ObjectMapper mapper,SmsNotificationService sms,@Value("${delivery.internal-key}") String key){deliveries=d;items=i;notifications=n;driverPresence=presence;orders=o;this.kafka=kafka;this.mapper=mapper;this.sms=sms;internalKey=key;}
 @Transactional public Map<String,Object> create(long orderId,long userId,String email,String phone,boolean smsOptIn,String address,BigDecimal amount,BigDecimal destLat,BigDecimal destLon,List<ItemInput> lines){boolean first=!deliveries.existsById(orderId);Delivery d=deliveries.findById(orderId).orElseGet(()->new Delivery(orderId,userId,email,phone,smsOptIn,address,amount,destLat,destLon));d=deliveries.save(d);items.deleteByOrderId(orderId);for(ItemInput x:lines)items.save(new DeliveryItem(orderId,x.name(),x.quantity()));if(first)notify(d,"Order placed","Your order has been confirmed and sent to the restaurant.");return view(d);}
 public List<Map<String,Object>> available(){return deliveries.findByDriverIdIsNullAndStatusOrderByUpdatedAtAsc("READY").stream().map(this::view).toList();} public List<Map<String,Object>> mine(long driver){return deliveries.findByDriverIdOrderByUpdatedAtDesc(driver).stream().map(this::view).toList();}
 @Transactional public Map<String,Object> accept(long id,long driver){Delivery d=find(id);if((d.getDriverId()!=null&&!d.getDriverId().equals(driver))||!"READY".equals(d.getStatus()))throw new IllegalStateException("Delivery is not available");d.assignDriver(driver);driverPresence.findById(driver).ifPresent(p->p.update(p.getLatitude(),p.getLongitude(),false));orders.updateStatus(internalKey,id,Map.of("status","OUT_FOR_DELIVERY"));notify(d,"Driver assigned","A driver is on the way with your order.");return view(d);}
 @Transactional public Map<String,Object> location(long order,long driver,BigDecimal lat,BigDecimal lon){Delivery d=deliveries.findByOrderIdAndDriverId(order,driver).orElseThrow(()->new SecurityException("Delivery is not assigned to you"));d.setLocation(lat,lon);driverPresence.findById(driver).ifPresent(p->p.update(lat,lon,false));return Map.of("orderId",order,"latitude",lat,"longitude",lon);}
 public Map<String,Object> location(long order){Delivery d=find(order);if(d.getDriverId()==null)throw new EntityNotFoundException("Driver has not been assigned yet");Map<String,Object> location=new LinkedHashMap<>();location.put("orderId",order);location.put("driverId",d.getDriverId());location.put("latitude",d.getLatitude());location.put("longitude",d.getLongitude());location.put("updatedAt",d.getUpdatedAt());return location;}
 @Transactional public Map<String,Object> status(long id,String next){Delivery d=find(id);d.setStatus(next);if("READY".equals(next))assignNearestDriver(d);orders.updateStatus(internalKey,id,Map.of("status",next));notify(d,"Order updated","Your order status is now "+next+".");return view(d);}
 @Transactional public Map<String,Object> presence(long driver,BigDecimal lat,BigDecimal lon,boolean available){DriverPresence p=driverPresence.findById(driver).orElseGet(()->new DriverPresence(driver,lat,lon,available));p.update(lat,lon,available);driverPresence.save(p);if(available)deliveries.findReadyForUpdate().stream().filter(d->d.getDeliveryLatitude()!=null&&d.getDeliveryLongitude()!=null).min(Comparator.comparingDouble(d->distanceKm(lat,lon,d.getDeliveryLatitude(),d.getDeliveryLongitude()))).filter(d->distanceKm(lat,lon,d.getDeliveryLatitude(),d.getDeliveryLongitude())<=15).ifPresent(d->{d.assignDriver(driver);p.update(lat,lon,false);notify(d,"Delivery assigned","A nearby ready order has been assigned to you.");});return Map.of("available",p.isAvailable(),"latitude",p.getLatitude(),"longitude",p.getLongitude());}
 public boolean assigned(long id,long driver){return deliveries.findByOrderIdAndDriverId(id,driver).isPresent();} public Map<String,Object> get(long id){return view(find(id));}
 public boolean ownerCanManage(long id,long owner){return Boolean.TRUE.equals(orders.ownerAccess(internalKey,id,owner).get("allowed"));}
 public List<Map<String,Object>> notifications(long uid){return notifications.findByUserIdOrderByCreatedAtDesc(uid).stream().map(n->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",n.getId());m.put("title",n.getTitle());m.put("message",n.getMessage());m.put("createdAt",n.getCreatedAt());m.put("read",n.getReadAt()!=null);m.put("readAt",n.getReadAt());return m;}).toList();}
 public long unreadCount(long uid){return notifications.countByUserIdAndReadAtIsNull(uid);}
 @Transactional public void markNotificationRead(long uid,long id){var n=notifications.findByIdAndUserId(id,uid).orElseThrow(()->new EntityNotFoundException("Notification not found"));n.markRead();}
 @Transactional public void markAllNotificationsRead(long uid){notifications.findByUserIdAndReadAtIsNull(uid).forEach(Notification::markRead);}
 private void notify(Delivery d,String title,String message){notifications.save(new Notification(d.getUserId(),title,message));if(d.getCustomerEmail()!=null&&!d.getCustomerEmail().isBlank())try{kafka.send("mail-requested",d.getCustomerEmail(),mapper.writeValueAsString(new MailRequest(d.getCustomerEmail(),title,message)));}catch(Exception e){throw new IllegalStateException("Could not queue customer email",e);}if(d.isSmsOptIn()&&d.getCustomerPhone()!=null&&!d.getCustomerPhone().isBlank())sms.send(d.getCustomerPhone(),title+": "+message);} private Delivery find(long id){return deliveries.findById(id).orElseThrow(()->new EntityNotFoundException("Delivery not found"));}
 private void assignNearestDriver(Delivery d){if(d.getDeliveryLatitude()==null||d.getDeliveryLongitude()==null)return;driverPresence.findAvailableForUpdate().stream().min(Comparator.comparingDouble(p->distanceKm(p.getLatitude(),p.getLongitude(),d.getDeliveryLatitude(),d.getDeliveryLongitude()))).filter(p->distanceKm(p.getLatitude(),p.getLongitude(),d.getDeliveryLatitude(),d.getDeliveryLongitude())<=15).ifPresent(p->{d.assignDriver(p.getUserId());p.update(p.getLatitude(),p.getLongitude(),false);notify(d,"A nearby driver has been assigned to your order.","Your delivery is ready for pickup.");});}
 private double distanceKm(BigDecimal lat1,BigDecimal lon1,BigDecimal lat2,BigDecimal lon2){double dLat=Math.toRadians(lat2.doubleValue()-lat1.doubleValue()),dLon=Math.toRadians(lon2.doubleValue()-lon1.doubleValue());double a=Math.sin(dLat/2)*Math.sin(dLat/2)+Math.cos(Math.toRadians(lat1.doubleValue()))*Math.cos(Math.toRadians(lat2.doubleValue()))*Math.sin(dLon/2)*Math.sin(dLon/2);return 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));}
 private Map<String,Object> view(Delivery d){List<Map<String,Object>> lines=items.findByOrderIdOrderById(d.getOrderId()).stream().map(x->Map.<String,Object>of("id",x.getId(),"itemName",x.getItemName(),"quantity",x.getQuantity())).toList();Map<String,Object> m=new LinkedHashMap<>();m.put("id",d.getOrderId());m.put("orderNumber","ORD-"+d.getOrderId());m.put("userId",d.getUserId());m.put("deliveryAddress",d.getDeliveryAddress());m.put("totalAmount",d.getTotalAmount());m.put("status",d.getStatus());m.put("driverId",d.getDriverId());m.put("latitude",d.getLatitude());m.put("longitude",d.getLongitude());m.put("deliveryLatitude",d.getDeliveryLatitude());m.put("deliveryLongitude",d.getDeliveryLongitude());m.put("items",lines);return m;}
 public record ItemInput(String name,int quantity){}
 public record MailRequest(String to,String subject,String body){}
}
